-- The car park list, version 2026-10-24: 30 car parks, 57 rates.
-- Written by `npm run carparks:sql` from src/carparks/carParkList.json; do not edit by hand.
on conflict (id) do update set
  name = excluded.name, area = excluded.area, lat = excluded.lat, lng = excluded.lng,
  source_url = excluded.source_url, checked_on = excluded.checked_on, notes = excluded.notes, updated_at = now();

-- A car park taken off the list takes its rate reports with it.
delete from public.car_park where id not in ('1-utama-shopping-centre', 'aeon-mall-shah-alam', 'bangsar-shopping-centre', 'berjaya-times-square', 'ioi-city-mall', 'ioi-mall-damansara', 'ioi-mall-puchong', 'kl-east-mall', 'lot-10', 'melawati-mall', 'mid-valley-megamall', 'mytown-shopping-centre', 'nu-empire-shopping-gallery', 'nu-sentral', 'paradigm-mall-petaling-jaya', 'pavilion-bukit-jalil', 'pavilion-kuala-lumpur', 'plaza-low-yat', 'publika', 'quill-city-mall', 'setia-city-mall', 'subang-parade', 'sunway-putra-mall', 'sunway-pyramid', 'sunway-velocity-mall', 'sunway-wangsa-mall', 'suria-klcc', 'the-curve', 'the-exchange-trx', 'the-gardens-mall');

delete from public.car_park_rate;
