insert into public.car_park (id, name, area, lat, lng, source_url, checked_on, notes) values
  ('1-utama-shopping-centre', '1 Utama Shopping Centre', 'Bandar Utama, Petaling Jaya', 3.14833, 101.61605, 'https://www.1utama.com.my/services/', '2026-10-24', 'Regular areas, without 1PAY (with 1PAY the first 4 hours are RM2). The outdoor Dataran car park charges per entry instead.'),
  ('aeon-mall-shah-alam', 'AEON Mall Shah Alam', 'Seksyen 13, Shah Alam', 3.07671, 101.54793, 'https://parkinginmalaysia.com/aeon-mall-shah-alam-parking-info/', '2026-10-24', 'From parkinginmalaysia.com; AEON publishes no rates. Non-member rate (members: first 2 hours free). No weekend rate: sources disagree (one says RM5 per entry).'),
  ('bangsar-shopping-centre', 'Bangsar Shopping Centre', 'Bangsar, Kuala Lumpur', 3.1431, 101.66733, 'https://www.bsc.com.my/centre-info/services', '2026-10-24', 'The mall gives one rate with no weekday or weekend split.'),
  ('berjaya-times-square', 'Berjaya Times Square', 'Jalan Imbi, Kuala Lumpur', 3.14249, 101.71035, 'https://www.motorist.my/article/2324/malaysia-s-mall-parking-rates-part-1-2026-update', '2026-10-24', 'The source''s table is dated 1 Feb 2022, so these may be out of date.'),
  ('ioi-city-mall', 'IOI City Mall', 'IOI Resort City, Putrajaya', 2.96984, 101.71422, 'https://www.ioicitymall.com.my/data/ckfinder/images/Parking_Rates_Signages_v5_FAOL_A4%281%29.jpg', '2026-10-24', 'From the mall''s signage (July 2025). An older mall FAQ shows RM2 and RM4 for the first hour.'),
  ('ioi-mall-damansara', 'IOI Mall Damansara', 'Kota Damansara, Petaling Jaya (formerly Tropicana Gardens Mall)', 3.14875, 101.59475, 'https://parking.com.my/item/tropicana-gardens-mall-kota-damansara/', '2026-10-24', 'Weekdays: first 3 hours free, 4th hour RM1, then RM2. Approximate on weekends: the 4th hour is RM1 (shown as RM2), and some sources say the first 3 hours are free there too. The mall says its rates are to be updated.'),
  ('ioi-mall-puchong', 'IOI Mall Puchong', 'Bandar Puchong Jaya, Puchong', 3.04521, 101.6182, 'https://ioimallpuchong.freshdesk.com/support/solutions/articles/150000204705-what-are-the-parking-rates-', '2026-10-24', null),
  ('kl-east-mall', 'KL East Mall', 'Desa Melawati, Kuala Lumpur', 3.22478, 101.73063, 'https://www.simedarbyproperty.com/malls/kleast-mall/', '2026-10-24', 'Prices exclude 8% service tax, so you pay about 8% more. Cashless only.'),
  ('lot-10', 'Lot 10', 'Bukit Bintang, Kuala Lumpur', 3.14635, 101.71198, 'https://www.comparehero.my/transportation/articles/mall-parking-rates', '2026-10-24', 'From CompareHero and Motorist, not the mall. Not included: weekday flat RM7 from 5pm to 7am. Weekends RM10 covers 8 hours; longer stays up to RM15.'),
  ('melawati-mall', 'Melawati Mall', 'Taman Melawati, Kuala Lumpur', 3.21118, 101.7488, 'https://www.melawatimall.com/mall-info/parking-rates', '2026-10-24', 'Same rate every day.'),
  ('mid-valley-megamall', 'Mid Valley Megamall', 'Mid Valley City, Kuala Lumpur', 3.11825, 101.67707, 'https://www.midvalley.com.my/locate/by-car/', '2026-10-24', 'Approximate: weekdays the 4th hour is RM1, so stays over 3 hours show RM1.50 more than charged. Free 15 minutes needs card validation at an Autopay station.'),
  ('mytown-shopping-centre', 'MyTOWN Shopping Centre', 'Cochrane, Cheras, Kuala Lumpur', 3.13476, 101.723, 'https://mytownkl.com.my/information', '2026-10-24', 'Also the IKEA Cheras car park. Not included: weekday early bird (entry before 9am, 8 to 12 hours RM7.70).'),
  ('nu-empire-shopping-gallery', 'NU Empire Shopping Gallery', 'SS16, Subang Jaya (formerly Empire Shopping Gallery)', 3.08203, 101.58267, 'https://parkinginmalaysia.com/nu-empire-shopping-gallery-ss16-parking-rate/', '2026-10-24', 'From parkinginmalaysia.com; the mall publishes no rates. Basement rates.'),
  ('nu-sentral', 'NU Sentral', 'KL Sentral, Brickfields, Kuala Lumpur', 3.13328, 101.68699, 'https://www.nusentral.com/', '2026-10-24', 'No public car rate found; check at the gantry.'),
  ('paradigm-mall-petaling-jaya', 'Paradigm Mall Petaling Jaya', 'Kelana Jaya, Petaling Jaya', 3.10512, 101.59591, 'https://www.paradigmmall.com.my/gettinghere.aspx?cid=3&CarPark', '2026-10-24', 'Approximate: from the 7th hour it is RM2 per hour, not RM1.'),
  ('pavilion-bukit-jalil', 'Pavilion Bukit Jalil', 'Bukit Jalil, Kuala Lumpur', 3.05106, 101.67051, 'https://www.pavilion-bukitjalil.com/about', '2026-10-24', 'The mall page also shows an older-looking second table (RM3 per hour, RM30 maximum); the first table is used. Check on site.'),
  ('pavilion-kuala-lumpur', 'Pavilion Kuala Lumpur', 'Bukit Bintang, Kuala Lumpur', 3.14939, 101.71299, 'https://malaysia.news.yahoo.com/plan-drive-pavilion-kl-parking-103415658.html', '2026-10-24', 'RM4 per hour, up to RM40 a day, from 1 Jan 2024 (Malay Mail; Motorist agrees). Not included: weekday flat RM10 per entry from 5pm to 7am.'),
  ('plaza-low-yat', 'Plaza Low Yat', 'Bukit Bintang, Kuala Lumpur', 3.14403, 101.71, 'https://plazalowyat.com/getting-here/', '2026-10-24', 'Not included: flat RM8 from 6pm to 6am. Touch ''n Go only.'),
  ('publika', 'Publika Shopping Gallery', 'Solaris Dutamas, Kuala Lumpur', 3.17119, 101.66579, 'https://www.publika.com.my/parking/daily-parking', '2026-10-24', 'Not included: weekday early-bird maximum (RM13 for entry 5am to 9am) at Basement 6 and 7 only.'),
  ('quill-city-mall', 'Quill City Mall', 'Jalan Sultan Ismail, Kuala Lumpur', 3.16, 101.70056, 'https://quillcitymall.com.my/getting-here/', '2026-10-24', 'Approximate: weekdays from the 5th hour it is RM3 per hour (capped at RM10). The day rate resets at 7am. No overnight parking.'),
  ('setia-city-mall', 'Setia City Mall', 'Setia Alam, Shah Alam', 3.10996, 101.45921, 'https://setiacitymall.com/index.php/getting-here/', '2026-10-24', 'Older listings still show the first 3 hours free on weekdays; the mall''s page no longer does.'),
  ('subang-parade', 'Subang Parade', 'SS16, Subang Jaya', 3.08219, 101.58552, 'https://parkinginmalaysia.com/subang-parade-parking-rate/', '2026-10-24', 'From parkinginmalaysia.com (the mall''s site was down); parking.com.my agrees. Basement rates, every day.'),
  ('sunway-putra-mall', 'Sunway Putra Mall', 'Jalan Putra, Kuala Lumpur', 3.16639, 101.69239, 'https://www.sunwayputramall.com/faq', '2026-10-24', 'Approximate: the 3rd hour is RM1, so stays over 2 hours show RM1 more than charged.'),
  ('sunway-pyramid', 'Sunway Pyramid', 'Bandar Sunway, Subang Jaya', 3.07249, 101.60655, 'https://www.sunwaypyramid.com/faq', '2026-10-24', 'Not included: the weekend rate also applies on the eve of a public holiday.'),
  ('sunway-velocity-mall', 'Sunway Velocity Mall', 'Cheras, Kuala Lumpur', 3.12679, 101.72502, 'https://www.sunwayvelocitymall.com/getting-here', '2026-10-24', 'Maximum RM20 per entry per day. No overnight parking.'),
  ('sunway-wangsa-mall', 'Sunway Wangsa Mall', 'Wangsa Maju, Kuala Lumpur (formerly Wangsa Walk Mall)', 3.19865, 101.7425, 'https://www.sunwaywangsamall.com/faqs', '2026-10-24', 'Not included: the weekend rate also applies on the eve of a public holiday. The mall says the rates were revised from 18 May 2026.'),
  ('suria-klcc', 'Suria KLCC', 'KLCC, Kuala Lumpur', 3.15738, 101.71238, 'https://www.suriaklcc.com.my/parking/', '2026-10-24', 'Approximate: weekdays the 2nd hour is RM5 (shown as RM4); weekends the 4th hour is RM5. Not included: weekday RM18 maximum from 5pm to 5am; Saturday before 12pm uses the weekday rate.'),
  ('the-curve', 'The Curve', 'Mutiara Damansara, Petaling Jaya', 3.15777, 101.6118, 'https://parking.com.my/item/the-curve/', '2026-10-24', 'From parking.com.my; the mall page could not be read. Sources disagree on a daily maximum (none, RM7.70 to RM9.90), and on whether 6% SST is on top.'),
  ('the-exchange-trx', 'The Exchange TRX', 'Tun Razak Exchange, Kuala Lumpur', 3.14254, 101.71808, 'https://theexchange.my/visit/getting-here', '2026-10-24', 'Not included: flat RM10 for entries between 5pm and 5am, every day.'),
  ('the-gardens-mall', 'The Gardens Mall', 'Mid Valley City, Kuala Lumpur', 3.11864, 101.67583, 'https://www.thegardensmall.com.my/parking', '2026-10-24', 'Same car park and rates as Mid Valley. Approximate: weekdays the 4th hour is RM1. No maximum. Free 15 minutes needs card validation.')
